declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_once __DIR__.'/_layout.php';$db=Database::connection();if($_SERVER['REQUEST_METHOD']==='POST'){Security::verifyCsrf($_POST['csrf']??null);if(isset($_POST['remove_id'])){Cart::remove((int)$_POST['remove_id']);}else{$action=(string)($_POST['action']??'');if($action==='add')Cart::add((int)($_POST['product_id']??0),(int)($_POST['quantity']??1));elseif($action==='update')Cart::update((array)($_POST['quantity']??[]));elseif($action==='remove')Cart::remove((int)($_POST['product_id']??0));}header('Location: /carrito.php');exit;}$items=Cart::detailed($db);$total=Cart::total($items);pageStart('Tu bolsa');?>
<main class="wrap"><div class="section-head"><div><span class="eyebrow">Tu selección</span><h2>Bolsa</h2></div></div><?php if($items===[]):?><div class="panel"><p>Tu bolsa está vacía.</p><a class="btn" href="/">Explorar colección</a></div><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=Security::e(Security::csrfToken())?>"><input type="hidden" name="action" value="update"><?php foreach($items as $item):?><div class="cart-row"><img src="<?=Security::e($item['imagen_url'])?>" alt=""><div><strong><?=Security::e($item['nombre'])?></strong><div class="muted">$<?=number_format((float)$item['precio'],0)?> MXN</div></div><input class="quantity" type="number" min="1" max="<?=(int)$item['stock']?>" name="quantity[<?=(int)$item['id']?>]" value="<?=(int)$item['cantidad']?>"><strong>$<?=number_format((float)$item['subtotal'],0)?></strong><button class="pill" formaction="/carrito.php" formmethod="post" name="remove_id" value="<?=(int)$item['id']?>">Quitar</button></div><?php endforeach;?><div class="panel" style="display:flex;justify-content:space-between;align-items:center;gap:18px;flex-wrap:wrap"><div><span class="muted">Total</span><div class="price">$<?=number_format($total,0)?> MXN</div></div><div class="actions"><button class="pill" type="submit">Actualizar</button><a class="btn" href="/checkout.php">Continuar compra</a></div></div></form><?php endif;?></main><?php pageEnd();?>
